/**
 * Cover of a timeline tile, without flickering:
 *
 * - Source chain: vault thumbnail (disk cache, works offline) → local
 *   thumbnail (system one on Android, generated here on desktop) → the
 *   local file itself, if it is a small image. If one fails, tries the next.
 *   Never the vault original: it would be a Telegram download per mounted
 *   cell (the vault thumbnail is generated by the queue, calmly).
 * - Swap without an empty frame: the current image stays until the next one is
 *   decoded (e.g. the vault thumbnail was just generated).
 */
import { useEffect, useState } from "react";
import { android, available as onAndroid } from "@tgcloud/ui/core/android";
import { thumbComing, thumbUrl } from "@tgcloud/ui/core/thumbs";
import { useThumbRev } from "@tgcloud/ui/core/server";
import { short, track } from "@tgcloud/ui/core/netlog";
import type { Media } from "../core/api";
import { deviceToken, tokenNow } from "../core/local";
import { failed as localFailed, generateLocal, localThumbUrl, ready as localReady } from "../shared/LocalThumb";

/** Already decoded in this session: remounting shows it right away. */
const decoded = new Set<string>();
/** Sources that failed (do not try again in this session). */
const broken = new Set<string>();

/** Local thumbnail (URL), `null` while resolving, `""` if there is none. */
function useLocal(uri: string | null, mime: string, misses: number): string | null {
  const [url, setUrl] = useState<string | null>(() => {
    if (!uri) return "";
    if (onAndroid) return android.deviceThumbNow(uri) || null;
    const t = tokenNow();
    if (!t) return null;
    return localFailed.has(uri) ? "" : localThumbUrl(t, uri);
  });
  useEffect(() => {
    if (!uri || url !== null) return;
    let alive = true;
    if (onAndroid) void android.deviceThumb(uri).then((u) => alive && setUrl(u));
    else void deviceToken().then((t) => alive && setUrl(t ? localThumbUrl(t, uri) : ""));
    return () => {
      alive = false;
    };
  }, [uri, url]);
  // Desktop: thumbnail not generated yet → generate it and reload.
  useEffect(() => {
    if (onAndroid || !uri || !url || !broken.has(url) || localReady.has(uri)) return;
    // Unmounted (left the screen) before its turn: generation is canceled.
    return generateLocal(uri, mime, () => setUrl(`${url.split("&v=")[0]}&v=${Date.now()}`));
  }, [uri, url, mime, misses]);
  return url;
}

function sources(m: Media, local: string | null): (string | null)[] {
  // In the device trash: only the kept thumbnail (the file is out of view).
  if (m.cover) return [m.cover];
  const small = m.mime.startsWith("image/") && m.size < 2 * 1024 * 1024 && !/heic|heif/.test(m.mime) ? (m.src ?? null) : null;
  // `null` = still resolving: wait before skipping to the next one.
  return m.thumb ? [thumbUrl(m.id), local, small] : [local, small];
}

export function Cover({ m, selected }: { m: Media; selected: boolean }) {
  // Thumbnail regenerated: the list does not change, only the URL; subscribes to swap the image.
  useThumbRev();
  const localUri = m.cover ? null : (m.uri ?? m.local ?? null);
  const [skip, setSkip] = useState(0);
  // Only fetches the local one if it can be used (no vault thumbnail, or it failed).
  const wantLocal = !!localUri && (!m.thumb || skip > 0);
  const local = useLocal(wantLocal ? localUri : null, m.mime, skip);
  const list = sources(m, wantLocal ? local : "");
  let url: string | null = null;
  for (let i = 0; i < list.length; i++) {
    const s = list[i];
    if (s === null) break; // resolving
    if (s && !broken.has(s)) {
      url = s;
      break;
    }
  }

  // Shown: only swaps when the new one is decoded.
  const [shown, setShown] = useState<string | null>(() => (url && decoded.has(url) ? url : null));
  useEffect(() => {
    if (!url || url === shown) return;
    if (decoded.has(url)) return setShown(url);
    let alive = true;
    const done = track(`miniatura ${short(url)} "${m.name}"`);
    const img = new Image();
    img.src = url;
    img
      .decode()
      .then(() => {
        done();
        decoded.add(url);
        if (alive) setShown(url);
      })
      .catch(() => {
        if (!alive) return;
        done("falhou");
        broken.add(url);
        setSkip((n) => n + 1);
      });
    return () => {
      alive = false;
      // Left the screen before arriving: release the request (otherwise it keeps
      // occupying one of the 6 connections the WebView opens per port).
      if (!decoded.has(url)) {
        done("cancelada (saiu da tela)");
        img.src = "";
      }
    };
  }, [url, shown]);

  const style = { transform: selected ? "scale(0.88)" : undefined, borderRadius: selected ? 8 : undefined };
  // No image yet: shimmer while it is on the way (decoding, or the vault
  // thumbnail is about to be generated); static background if it will not appear.
  if (!shown) {
    const loading = !!url || list.some((s) => s === null) || (!m.thumb && m.id > 0 && thumbComing(m));
    return <div className={`size-full transition-transform duration-200 ${loading ? "skeleton rounded-none" : "bg-s3"}`} style={style} />;
  }
  return <img src={shown} alt="" draggable={false} decoding="sync" className="size-full object-cover transition-transform duration-200" style={style} />;
}
